/**
 * Errors the engine reports across the FFI boundary. Maps one-to-one to the
 * Swift `MLSError` (plan table); `.busy` exists only on the Swift side.
 */
public enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Malformed
    case UnknownGroup
    case NotMember
    case Duplicate
    /**
     * The message belongs to a later epoch than the stored group: a commit was missed.
     */
    case EpochGap
    case PendingCommit
    /**
     * A staged `process` can no longer be confirmed: the group's stored state
     * changed since it was staged (or it was already confirmed or discarded).
     */
    case Stale
    /**
     * `decrypt_application` was given something that is not an application message.
     */
    case NotApplication
    case Storage(String
    )
    case Crypto(String
    )
    case Internal(String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FfiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Malformed
        case 2: return .UnknownGroup
        case 3: return .NotMember
        case 4: return .Duplicate
        case 5: return .EpochGap
        case 6: return .PendingCommit
        case 7: return .Stale
        case 8: return .NotApplication
        case 9: return .Storage(
            try FfiConverterString.read(from: &buf)
            )
        case 10: return .Crypto(
            try FfiConverterString.read(from: &buf)
            )
        case 11: return .Internal(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .Malformed:
            writeInt(&buf, Int32(1))
        
        
        case .UnknownGroup:
            writeInt(&buf, Int32(2))
        
        
        case .NotMember:
            writeInt(&buf, Int32(3))
        
        
        case .Duplicate:
            writeInt(&buf, Int32(4))
        
        
        case .EpochGap:
            writeInt(&buf, Int32(5))
        
        
        case .PendingCommit:
            writeInt(&buf, Int32(6))
        
        
        case .Stale:
            writeInt(&buf, Int32(7))
        
        
        case .NotApplication:
            writeInt(&buf, Int32(8))
        
        
        case let .Storage(v1):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Crypto(v1):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Internal(v1):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(v1, into: &buf)
            
        }
    }
}


